import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";
import { SELLERS, PROMOS } from "./data.js";

const BUILD = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(BUILD, "..");
const RESOURCES = path.join(BUILD, "resources");

const argv = process.argv.slice(2);
const flag = name => {
  const at = argv.indexOf(name);
  if (at === -1) return null;
  const value = argv[at + 1];
  if (!value || value.startsWith("--")) throw Error(`${name} needs a value`);
  return value;
};
const outArg = flag("--out") ?? process.env.OUT;
const DEFAULT_OUT = path.join(ROOT, "site");
const OUT = outArg ? path.resolve(ROOT, outArg) : DEFAULT_OUT;
const MINIFY = !argv.includes("--no-minify") && process.env.MINIFY !== "0";

// only meaningful at the domain root, and the repo root is no longer it
const ROOT_FILES = ["CNAME", "robots.txt"];
// the marker that says a folder is safe to wipe. OUT is user-settable, and a
// clean build that rm -rf's whatever it is pointed at is one typo from disaster
const STAMP = ".build-output";
const STAMP_TEXT = "generated by build/build.js -- safe to delete\n";

/* ---------- cache-busting ---------- */

const SHIP = [["calc.js", "js"], ["app.js", "js"], ["main.css", "css"]];
const TOKENS = {
  "app.js": { __DATA__: "data.json", __CALC__: "calc.js" },
  "shell.html": { __CSS__: "main.css", __APP__: "app.js" },
};
const VERSIONS = {};
const version = text => crypto.createHash("sha1").update(text).digest("hex").slice(0, 8);

// a missing token fails the build rather than shipping an unversioned url
function stamp(text, file) {
  for (const [token, of] of Object.entries(TOKENS[file] || {})) {
    if (!text.includes(token)) throw Error(`${file} has no ${token}`);
    if (!VERSIONS[of]) throw Error(`${file} needs ${of} shipped first`);
    text = text.replaceAll(token, VERSIONS[of]);
  }
  return text;
}

/* ---------- vocabulary ---------- */

const esc = text => String(text)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const RATING = {
  good: { emoji: "🔥", chip: "Worth it", label: "Worth doing" },
  meh: { emoji: "💤", chip: "Meh", label: "Average or low reward" },
  bad: { emoji: "💀", chip: "Avoid", label: "Bad deal / scammy" },
};

const FACETS = {
  rating: {
    label: "Rating",
    attr: "r",
    options: Object.entries(RATING).map(([key, { emoji, chip }]) => [key, `${emoji} ${chip}`]),
  },
  payout: {
    label: "Payout",
    attr: "p",
    options: ["Cash", "Credit", "Coupons", "Discount", "Gift"].map(v => [v, v]),
  },
  accepts: {
    label: "Accepts",
    attr: "a",
    options: ["Credit", "Coupons", "Discounts", "None"].map(v => [v, v]),
  },
  type: {
    label: "Type",
    attr: "t",
    options: ["Daily claim", "Cashout", "Coupon Bundle"].map(v => [v, v]),
  },
};

const SELLER_BADGE = {
  local: { emoji: "🚛", label: "Local warehouse", title: "Ships from inside your country/region or nearby, so orders tend to show up faster", legend: "means the seller ships from inside your country/region or somewhere nearby, so orders tend to show up faster." },
  star: { emoji: "🌟", label: "Star store", title: "Ranked among the top 5% of sellers in its main category over the past 30 days, on sales and review ratings combined", legend: "means the store ranked in the top 5% of its main product category over the past 30 days, counting sales and review ratings together." },
  fast: { emoji: "🏎️", label: "Fast delivery", title: "Among the top 10% in its category over the past 30 days for how quickly orders ship out and arrive", legend: "means the store ranked in the top 10% of its category over the past 30 days for how quickly orders ship out and arrive." },
  veteran: { emoji: "🗓️", label: "Established store", title: "Has been selling on Temu for more than a year", legend: "means the store has been selling on Temu for more than a year." },
  handmade: { emoji: "🖐️", label: "Handmade", title: "More than half the items sold are handmade", legend: "means more than half the items the store sells are handmade." },
  design: { emoji: "✒️", label: "Original design", title: "More than half the items sold are original designs", legend: "means more than half the items the store sells are original designs." },
  eco: { emoji: "🌿", label: "Eco-friendly", title: "More than half the items sold are eco-friendly", legend: "means more than half the items the store sells are eco-friendly." },
  packGood: { emoji: "📦", label: "Great packaging/shipping", title: "Orders from this seller have shown up well protected", legend: "means orders from this seller have shown up well protected." },
  packBad: { emoji: "💥", label: "Terrible packaging/shipping", title: "Orders from this seller have shown up damaged or badly packed", legend: "means orders from this seller have shown up damaged or badly packed." },
};
const BAR_CLASSES = ["s5", "s4", "s3", "s2", "s1"];
const HIDDEN_BADGES = new Set(["local"]);
const USED_BADGES = new Set(SELLERS.flatMap(seller => seller.badges));
const TAB_LABEL = { farmland: "Farmland" };

/* ---------- helpers ---------- */

const icon = name => `<svg class="i-${name}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const number = value => value.toLocaleString("en-US");
const ratingOf = promo => RATING[promo.rating] ? promo.rating : "meh";
const shotsOf = promo => promo.images || [];
// "Cash*" -> "Cash". the star means "not always offered" and is shown, not filtered on
const clean = values => (values || []).map(value => String(value).replace(/\*$/, ""));
const hasCalc = promo => !!promo.calc;

function updatedText(promo) {
  if (!promo.date) return "";
  const day = new Date(promo.date + "T00:00:00Z");
  return "Rules last updated " + day.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
}

const hiddenWords = promo => [
  ...promo.rules.map(rule => rule.t),
  ...shotsOf(promo).map(shot => shot.caption || ""),
].join(" ").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim().toLowerCase();

/* ---------- validation ---------- */

function validatePromo(promo) {
  const fail = message => { throw Error(`${promo.id}: ${message}`); };
  for (const [facet, { options }] of Object.entries(FACETS)) {
    if (facet === "rating") continue;
    const allowed = options.map(([option]) => option);
    for (const value of clean(promo[facet])) {
      if (!allowed.includes(value)) fail(`${facet} "${value}" is not one of ${allowed.join(", ")}`);
    }
  }
  if (promo.rating && !RATING[promo.rating]) fail(`rating "${promo.rating}" is not one of ${Object.keys(RATING).join(", ")}`);
  if (promo.tab && !TAB_LABEL[promo.tab]) fail(`tab "${promo.tab}" is not one of ${Object.keys(TAB_LABEL).join(", ")}`);
  if (promo.date) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(promo.date)) fail(`date "${promo.date}" is not YYYY-MM-DD`);
    if (isNaN(new Date(promo.date + "T00:00:00Z"))) fail(`date "${promo.date}" is not a real date`);
  }
}

function validateSeller(seller) {
  const fail = message => { throw Error(`${seller.name || seller.url || "a seller"}: ${message}`); };
  for (const key of seller.badges) {
    if (!SELLER_BADGE[key]) fail(`badge "${key}" is not one of ${Object.keys(SELLER_BADGE).join(", ")}`);
  }
  if (seller.bars.length !== BAR_CLASSES.length) fail(`bars needs ${BAR_CLASSES.length} entries, got ${seller.bars.length}`);
  for (const value of [seller.rating, seller.reviews, ...seller.bars]) {
    if (typeof value !== "number" || !isFinite(value)) fail(`"${value}" is not a number`);
  }
  if (seller.website && !/^https?:\/\//i.test(seller.website)) fail(`website "${seller.website}" has to start with http:// or https://`);
}

/* ---------- promo cards ---------- */

function factHtml(label, values) {
  const known = values && values.length;
  return `<div class="fact"><span>${label}</span><b${known ? "" : ' class="unk"'}>${known ? esc(values.join(", ")) : "Unknown"}</b></div>`;
}

function codesHtml(promo) {
  return promo.codes.map(code => `
        <div class="code">
          <code>${esc(code)}</code>
          <button type="button" data-code="${esc(code)}" aria-label="Copy code ${esc(code)}">Copy</button>
        </div>`).join("");
}

function shotsHtml(promo) {
  const shots = shotsOf(promo);
  if (!shots.length) return "";
  const figures = shots.map(shot => `
          <figure>
            <button type="button" class="shot" aria-label="Open screenshot: ${esc(shot.caption || promo.name)}">
              <img src="${esc(shot.src)}" loading="lazy" decoding="async" alt="">
            </button>
            ${shot.caption ? `<figcaption>${esc(shot.caption)}</figcaption>` : ""}
          </figure>`).join("");
  return `
        <div class="shots">${figures}
        </div>`;
}

function rulesHtml(promo) {
  const list = promo.rules.length
    ? `
        <ul class="rules">${promo.rules.map(rule => `
          <li${rule.warn ? ' class="warn"' : ""}>${rule.t}</li>`).join("")}
        </ul>`
    : "";
  const pending = promo.pending || !promo.rules.length
    ? `
        <p class="todo">Not finished yet - Coming soon!</p>`
    : "";
  return list + pending;
}

function facetAttrs(promo, rating) {
  return Object.entries(FACETS).map(([facet, { attr }]) => {
    const values = facet === "rating" ? [rating] : clean(promo[facet]);
    return values.length ? ` data-${attr}="${esc(values.join(","))}"` : "";
  }).join("");
}

function cardHtml(promo) {
  const rating = ratingOf(promo);
  const { emoji, label } = RATING[rating];
  const name = esc(promo.name);
  const id = esc(promo.id);
  const starred = [promo.type, promo.accepts, promo.payout]
    .flatMap(values => values || [])
    .some(value => String(value).endsWith("*"));
  const detail = promo.tab
    ? `
        <button type="button" class="go" data-tab="${esc(promo.tab)}">Open the ${esc(TAB_LABEL[promo.tab])} tab</button>`
    : shotsHtml(promo) + rulesHtml(promo);
  const foot = promo.terms || hasCalc(promo)
    ? `
        <div class="foot-row">${promo.terms ? `
          <button type="button" class="info" data-open="rules" aria-haspopup="dialog">${icon("rules")}Rules</button>` : ""}${hasCalc(promo) ? `
          <button type="button" class="info" data-open="calc" aria-haspopup="dialog">${icon("calc")}Calculator</button>` : ""}
        </div>`
    : "";
  const shortcuts = hasCalc(promo) ? `
        <button type="button" class="icon" data-open="calc" aria-haspopup="dialog" aria-label="Calculator for ${name}" title="Calculator">${icon("calc")}</button>` : "";
  // the card shows a tab link instead of its detail, so search still needs the words
  const unlisted = promo.tab ? ` data-s="${esc(hiddenWords(promo))}"` : "";

  return `
    <article class="card promo" id="p-${id}" data-id="${id}"${facetAttrs(promo, rating)}${unlisted}>
      <div class="head">
        <span class="star ${rating}" role="img" title="${label}" aria-label="${label}">${emoji}</span>
        <h2><button type="button" class="toggle" aria-expanded="false" aria-controls="b-${id}">${name}</button></h2>${shortcuts}
        <button type="button" class="icon fav" aria-pressed="false" aria-label="Add ${name} to favorites">${icon("star")}</button>
        <button type="button" class="icon chevbtn" tabindex="-1" aria-hidden="true"><span class="chev">${icon("chev")}</span></button>
      </div>
      <div class="codes">${codesHtml(promo)}
      </div>
      <div class="facts">${factHtml("Type", promo.type)}${factHtml("Accepts", promo.accepts)}${factHtml("Payout", promo.payout)}${starred ? `<p class="fact-note">* not always offered</p>` : ""}</div>
      <div class="body" id="b-${id}">${promo.reward ? `
        <p class="reward">${promo.reward}</p>` : ""}${detail}${foot}
      </div>
    </article>`;
}

function tabPanelHtml(promo) {
  const updated = updatedText(promo);
  return `
      <div class="card">
        <h2>${esc(promo.name)}</h2>${promo.reward ? `
        <p class="reward">${promo.reward}</p>` : ""}${shotsHtml(promo)}${rulesHtml(promo)}${updated ? `
        <p class="fact-note">${updated}</p>` : ""}
      </div>`;
}

/* ---------- sellers ---------- */

function regionOf(address) {
  const parts = String(address || "").split(",").map(part => part.trim()).filter(Boolean);
  if (!parts.length) return "";
  const country = parts[parts.length - 1];
  if (parts.length < 2 || !/^(United States|USA?)$/i.test(country)) return country;
  return parts[parts.length - 2].replace(/\s+\d{5}(-\d{4})?$/, "");
}

function soldCount(sold) {
  const scale = /M/i.test(sold) ? 1e6 : /K/i.test(sold) ? 1e3 : 1;
  return parseFloat(sold) * scale;
}

function sellerHtml(seller) {
  const name = esc(seller.name);
  const badges = seller.badges.filter(key => !HIDDEN_BADGES.has(key)).map(key => {
    const { emoji, title } = SELLER_BADGE[key];
    return `<span class="seller-badge" role="img" data-badge="${key}" title="${esc(title)}" aria-label="${esc(title)}">${emoji}</span>`;
  }).join("");
  const barSummary = seller.bars.map((percent, i) => `${5 - i}★ ${percent}%`).join(" · ");
  const barSegments = seller.bars.map((percent, i) =>
    percent ? `<span class="${BAR_CLASSES[i]}" style="flex:${percent}" title="${5 - i}★ ${percent}%"></span>` : ""
  ).join("");
  const breakdown = seller.bars.map((percent, i) => {
    const stars = 5 - i;
    const fill = percent ? `<span class="${BAR_CLASSES[i]}" style="--p:${percent}%"></span>` : "";
    return `
          <span class="dist-n">${stars}</span><span class="dist-stars">${"★".repeat(stars)}<i>${"☆".repeat(5 - stars)}</i></span><span class="dist-track">${fill}</span><span class="dist-pct">${percent.toFixed(1)}%</span>`;
  }).join("");
  const from = regionOf(seller.address);
  const site = seller.website
    ? `<a class="seller-site" href="${esc(seller.website)}" target="_blank" rel="noopener noreferrer" title="Seller's own website" aria-label="${name}'s own website">🌐</a>`
    : "";

  return `
    <article class="seller card" data-badges="${seller.badges.join(" ")}" data-free="${seller.shipping === "Free" ? 1 : 0}" data-rating="${seller.rating}" data-reviews="${seller.reviews}" data-sold="${soldCount(seller.sold)}">
      <img class="seller-avatar" src="${esc(seller.avatar)}" alt="" loading="lazy" decoding="async">
      <div class="seller-main">
        <div class="seller-top">
          <span class="seller-name"><a class="seller-link" href="${esc(seller.url)}" target="_blank" rel="noopener noreferrer"><span>${name}</span>${icon("ext")}</a>${site}</span>
          <span class="seller-rating">${seller.rating.toFixed(1)} <b>★</b> <small>${number(seller.reviews)} reviews</small></span>
        </div>
        <div class="seller-badges">${badges}</div>
      </div>
      <div class="seller-ship">
        <div class="seller-min"><span class="lbl lbl-m">Shipping:</span><span class="lbl lbl-d">Shipping minimum</span><b>${esc(seller.shipping)}</b></div>${from ? `
        <div class="seller-from lbl"><span>From:</span>${esc(from)}</div>` : ""}
      </div>
      <div class="seller-sold">
        <span class="lbl lbl-d">Sold</span><b>${esc(seller.sold)}</b><span class="sold-m"> sold <i>·</i> <b>${number(seller.reviews)}</b> reviews</span>
      </div>
      <div class="seller-ratings">
        <span class="lbl lbl-d">Ratings</span>
        <div class="seller-bars" role="img" aria-label="${barSummary}">${barSegments}</div>
        <div class="seller-dist" aria-hidden="true">${breakdown}
        </div>
      </div>
    </article>`;
}

/* ---------- facet chips, legends ---------- */

function facetsHtml() {
  const group = (label, chips) =>
    `<fieldset class="facet"><legend>${label}</legend><div class="chips">${chips}</div></fieldset>`;
  const chip = (key, label, extra = "") =>
    `<button type="button" class="chip${extra}" aria-pressed="false" data-key="${esc(key)}">${label}</button>`;

  let html = "";
  for (const [facet, entry] of Object.entries(FACETS)) {
    html += group(entry.label, entry.options.map(([value, label]) => chip(facet + "|" + value, label)).join(""));
  }
  return html + group("Favorites", chip("fav", icon("star") + "Favorites only", " fav"));
}

const legendHtml = () => Object.values(RATING)
  .map(({ emoji, chip }) => `${emoji} ${chip.toLowerCase()}`).join(" · ");

function sellerKeyHtml() {
  return Object.entries(SELLER_BADGE)
    .filter(([key]) => USED_BADGES.has(key) && !HIDDEN_BADGES.has(key))
    .map(([, badge]) => `<p><b>${badge.emoji} ${esc(badge.label)}</b> ${esc(badge.legend)}</p>`)
    .join("");
}

/* ---------- assemble ---------- */

PROMOS.forEach(validatePromo);
SELLERS.forEach(validateSeller);

const SLOTS = {
  "<!--PROMOS-->": PROMOS.map(cardHtml).join(""),
  "<!--SELLERS-->": SELLERS.map(sellerHtml).join(""),
  "<!--FACETS-->": facetsHtml(),
  "<!--LEGEND-->": legendHtml(),
  "<!--COUNT-->": `${PROMOS.length} promos`,
  "<!--SELLERCOUNT-->": `${SELLERS.length} sellers`,
  "<!--SELLERKEY-->": sellerKeyHtml(),
};
for (const tab of Object.keys(TAB_LABEL)) {
  SLOTS[`<!--${tab.toUpperCase()}-->`] = PROMOS.filter(promo => promo.tab === tab).map(tabPanelHtml).join("");
}

let html = fs.readFileSync(path.join(BUILD, "shell.html"), "utf8");
for (const [slot, value] of Object.entries(SLOTS)) {
  if (!html.includes(slot)) throw Error(`shell.html has no ${slot}`);
  html = html.replaceAll(slot, () => value);
}

const detail = { t: {}, c: {} };
for (const promo of PROMOS) {
  if (promo.terms) detail.t[promo.id] = { t: promo.terms, u: updatedText(promo) };
  if (hasCalc(promo)) detail.c[promo.id] = promo.calc;
}
const dataJson = JSON.stringify(detail);

/* ---------- output folder ---------- */

function resetOut() {
  if (fs.existsSync(OUT)) {
    const existing = fs.readdirSync(OUT);
    const ours = OUT === DEFAULT_OUT || !existing.length || existing.includes(STAMP);
    if (!ours) {
      throw Error(
        `refusing to overwrite ${OUT}\n` +
        `  it already has files in it and no previous build of this site wrote them.\n` +
        `  delete the folder yourself if you meant to replace it, or point --out somewhere else.`
      );
    }
    fs.rmSync(OUT, { recursive: true, force: true });
  }
  fs.mkdirSync(OUT, { recursive: true });
  fs.writeFileSync(path.join(OUT, STAMP), STAMP_TEXT);
}

function copyResources() {
  if (!fs.existsSync(RESOURCES)) throw Error(`${RESOURCES} is missing`);
  fs.cpSync(RESOURCES, OUT, { recursive: true });
}

/* ---------- minify ---------- */

const ESBUILD_HELP = "run npm install, or build with --no-minify to ship the sources as they are";

async function loadEsbuild() {
  let api;
  try {
    const loaded = await import("esbuild");
    api = loaded.default ?? loaded;
  } catch {
    throw Error(`esbuild is not installed -- ${ESBUILD_HELP}`);
  }
  try {
    api.transformSync("", { loader: "js" });
  } catch (error) {
    throw Error(`esbuild cannot run here -- ${ESBUILD_HELP}\n  (${error.message.split("\n")[0]})`);
  }
  return api;
}

const esbuild = MINIFY ? await loadEsbuild() : null;

function shipSource(name, loader) {
  const source = stamp(fs.readFileSync(path.join(BUILD, name), "utf8"), name);
  if (!MINIFY) {
    fs.writeFileSync(path.join(OUT, name), source);
    VERSIONS[name] = version(source);
    return;
  }
  const { code, map } = esbuild.transformSync(source, {
    loader,
    minify: true,
    sourcemap: true,
    sourcesContent: true,
    sourcefile: `build/${name}`,
    legalComments: "none",
    ...(loader === "js" ? { target: "es2020" } : {}),
  });
  const link = loader === "css" ? `\n/*# sourceMappingURL=${name}.map */\n` : `\n//# sourceMappingURL=${name}.map\n`;
  const shipped = code + link;
  fs.writeFileSync(path.join(OUT, name), shipped);
  fs.writeFileSync(path.join(OUT, `${name}.map`), map);
  VERSIONS[name] = version(shipped);
}

/* ---------- write ---------- */

VERSIONS["data.json"] = version(dataJson);

resetOut();
copyResources();
for (const [name, loader] of SHIP) shipSource(name, loader);
for (const file of ROOT_FILES) fs.copyFileSync(path.join(ROOT, file), path.join(OUT, file));
fs.writeFileSync(path.join(OUT, "index.html"), stamp(html, "shell.html"));
fs.writeFileSync(path.join(OUT, "data.json"), dataJson);

/* ---------- report ---------- */

const shipped = SHIP.map(([name]) => name);
const kb = bytes => ((bytes / 1024).toFixed(1) + " KB").padStart(9);
const size = file => kb(fs.statSync(path.join(OUT, file)).size);
for (const file of ["index.html", "data.json", ...shipped, ...ROOT_FILES]) {
  console.log(file.padEnd(11), size(file));
}

let files = 0, bytes = 0;
for (const entry of fs.readdirSync(OUT, { recursive: true, withFileTypes: true })) {
  const parent = entry.parentPath ?? entry.path;
  if (entry.isFile()) { files++; bytes += fs.statSync(path.join(parent, entry.name)).size; }
}

const unusedBadges = Object.keys(SELLER_BADGE).filter(key => !USED_BADGES.has(key));
const shipList = [...shipped, "data.json"];
const widths = shipList.map(name => Math.max(name.length, VERSIONS[name].length));
const row = cells => cells.map((cell, i) => cell.padEnd(widths[i])).join("  ").trimEnd();

console.log("-".repeat(21));
console.log("total".padEnd(11), kb(bytes), `in ${files} files`);
console.log("minify".padEnd(11), MINIFY ? "on, with sourcemaps" : "OFF (--no-minify)");
console.log("out".padEnd(11), path.relative(ROOT, OUT) || OUT);
console.log("versions".padEnd(11), row(shipList));
console.log("".padEnd(11), row(shipList.map(name => VERSIONS[name])));
console.log("calculators".padEnd(11), PROMOS.filter(hasCalc).map(promo => promo.id).join("  "));
console.log("badges".padEnd(11), "used:", [...USED_BADGES].join(", "));
if (unusedBadges.length) console.log("".padEnd(11), " not:", unusedBadges.join(", "));
